package com.personal.meditation;
import android.app.*;import android.content.*;import android.content.pm.ServiceInfo;import android.os.*;import org.json.*;
/** A user-started foreground session keeps cue deadlines alive with the screen off. */
public final class MeditationService extends Service {
 static final String START="start",PAUSE="pause",RESUME="resume",STOP="stop";static volatile String snapshot="{\"phase\":\"idle\",\"remainingMs\":0,\"quarter\":1}";static volatile boolean busy;
 private final Handler handler=new Handler(Looper.getMainLooper());private final SessionClock clock=new SessionClock();private CuePlayer player;private Settings settings;private JSONObject config;private PowerManager.WakeLock wake;private Vibrator vibrator;private int generation;private long lastNotification;private boolean foreground;
 private final Runnable tick=new Runnable(){public void run(){long now=SystemClock.elapsedRealtime();SessionClock.Cue cue=clock.poll(now);if(cue!=null)cue(cue);publish(now);if(clock.active(now)){handler.postDelayed(this,100);}else if(!clock.phase(now).equals("finished"))shutdown(false);}};
 @Override public void onCreate(){super.onCreate();settings=new Settings(this);player=new CuePlayer(this);vibrator=(Vibrator)getSystemService(VIBRATOR_SERVICE);NotificationChannel channel=new NotificationChannel("meditation_session","Meditation timer",NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);channel.enableVibration(false);getSystemService(NotificationManager.class).createNotificationChannel(channel);wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,getPackageName()+":meditation");wake.setReferenceCounted(false);}
 @Override public int onStartCommand(Intent intent,int flags,int id){String action=intent==null?STOP:intent.getAction();long now=SystemClock.elapsedRealtime();if(START.equals(action)){if(busy)return START_NOT_STICKY;generation++;player.stop();cancelVibration();release();config=settings.get();try{clock.start(now,config.getInt("minutes")*60000L);}catch(JSONException invalid){stopSelf();return START_NOT_STICKY;}busy=true;foreground=true;Notification n=notification(now);if(Build.VERSION.SDK_INT>=29)startForeground(1,n,ServiceInfo.FOREGROUND_SERVICE_TYPE_MEDIA_PLAYBACK);else startForeground(1,n);acquire();handler.removeCallbacks(tick);tick.run();}
 else if(PAUSE.equals(action)&&busy){SessionClock.Cue due=clock.poll(now);if(due!=null)cue(due);if(clock.active(now)){clock.pause(now);handler.removeCallbacks(tick);player.stop();cancelVibration();release();}publish(now);}
 else if(RESUME.equals(action)&&busy){clock.resume(now);acquire();handler.removeCallbacks(tick);tick.run();}
 else if(STOP.equals(action))shutdown(true);return START_NOT_STICKY;}
 private void acquire(){if(wake!=null&&!wake.isHeld())wake.acquire(Math.max(60000,clock.remaining(SystemClock.elapsedRealtime())+clock.duration()+120000));}
 private void release(){if(wake!=null&&wake.isHeld())wake.release();}
 private void cancelVibration(){if(vibrator!=null)vibrator.cancel();}
 private void vibrate(String key){try{JSONObject v=config.getJSONObject("vibrations").getJSONObject(key);if(v.getBoolean("enabled")&&vibrator!=null&&vibrator.hasVibrator())vibrator.vibrate(VibrationEffect.createOneShot(v.getInt("ms"),VibrationEffect.DEFAULT_AMPLITUDE));}catch(JSONException ignored){}}
 private void sound(String role,Runnable done){try{player.play(config.getString(role),settings.prefs.getString(role+"Uri",""),done);}catch(JSONException ignored){done.run();}}
 private void cue(SessionClock.Cue cue){switch(cue){case SHORT_ONE:case SHORT_TWO:vibrate("prepShort");break;case LONG:vibrate("prepLong");break;case START:cancelVibration();vibrate("start");sound("bell",()->{});break;case QUARTER_ONE:case QUARTER_TWO:case QUARTER_THREE:vibrate("quarter");sound("quarter",()->{});break;case END:cancelVibration();vibrate("end");busy=false;int token=generation;long finishAfter=nowForEnd();sound("bell",()->handler.postDelayed(()->{if(token==generation&&clock.phase(SystemClock.elapsedRealtime()).equals("finished"))shutdown(false);},Math.max(0,finishAfter-SystemClock.elapsedRealtime())));break;}}
 private long nowForEnd(){try{JSONObject value=config.getJSONObject("vibrations").getJSONObject("end");return SystemClock.elapsedRealtime()+(value.getBoolean("enabled")?value.getInt("ms"):0);}catch(JSONException ignored){return SystemClock.elapsedRealtime();}}
 private void publish(long now){String phase=clock.phase(now);try{snapshot=new JSONObject().put("phase",phase).put("period",clock.period(now)).put("remainingMs",clock.remaining(now)).put("durationMs",clock.duration()).put("quarter",clock.quarter(now)).toString();}catch(JSONException ignored){}if(foreground&&(now-lastNotification>=1000||phase.equals("paused")||phase.equals("finished"))){lastNotification=now;getSystemService(NotificationManager.class).notify(1,notification(now));}}
 static String time(long ms){long seconds=(ms+999)/1000;return String.format(java.util.Locale.US,"%02d:%02d",seconds/60,seconds%60);}
 private PendingIntent action(String name,int request){return PendingIntent.getService(this,request,new Intent(this,MeditationService.class).setAction(name),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private Notification notification(long now){String phase=clock.phase(now),label=phase.equals("preparing")?"Get comfortable":phase.equals("paused")?"Paused":phase.equals("finished")?"Session complete":"Meditating";PendingIntent open=PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder builder=new Notification.Builder(this,"meditation_session").setSmallIcon(R.drawable.ic_notification).setContentTitle("Meditation · "+time(clock.remaining(now))).setContentText(label).setContentIntent(open).setOnlyAlertOnce(true).setOngoing(true).setCategory(Notification.CATEGORY_PROGRESS);if(!phase.equals("finished"))builder.addAction(new Notification.Action.Builder(null,phase.equals("paused")?"Resume":"Pause",action(phase.equals("paused")?RESUME:PAUSE,1)).build());builder.addAction(new Notification.Action.Builder(null,"End",action(STOP,2)).build());return builder.build();}
 private void shutdown(boolean reset){generation++;handler.removeCallbacks(tick);if(reset){clock.stop();snapshot="{\"phase\":\"idle\",\"remainingMs\":0,\"quarter\":1}";}busy=false;player.stop();cancelVibration();release();if(foreground){stopForeground(STOP_FOREGROUND_REMOVE);foreground=false;}stopSelf();}
 @Override public void onDestroy(){handler.removeCallbacks(tick);player.stop();cancelVibration();release();if(clock.active(SystemClock.elapsedRealtime()))snapshot="{\"phase\":\"idle\",\"remainingMs\":0,\"quarter\":1}";busy=false;super.onDestroy();}
 @Override public IBinder onBind(Intent intent){return null;}
}
